CREATE DATABASE IF NOT EXISTS ezshift_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ezshift_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS notifications,reviews,invoices,booking_workers,drivers,booking_services,booking_items,payments,contact_messages,bookings,workers,vehicles,services,inventory_items,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40),address VARCHAR(255),password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE workers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(40),employee_id VARCHAR(40) UNIQUE,specialization VARCHAR(80),experience TINYINT UNSIGNED DEFAULT 0,rating DECIMAL(2,1) DEFAULT 5.0,status ENUM('Available','Assigned','Busy','Unavailable') DEFAULT 'Available') ENGINE=InnoDB;
CREATE TABLE drivers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(40),license_number VARCHAR(50) UNIQUE,experience TINYINT UNSIGNED DEFAULT 0,status ENUM('Available','Assigned','Unavailable') DEFAULT 'Available') ENGINE=InnoDB;
CREATE TABLE vehicles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,vehicle_number VARCHAR(30),model VARCHAR(80),capacity VARCHAR(80),base_price DECIMAL(10,2) DEFAULT 0,price_per_km DECIMAL(8,2) DEFAULT 0,status ENUM('Available','Assigned','In Transit','Maintenance','Unavailable') DEFAULT 'Available') ENGINE=InnoDB;
CREATE TABLE services(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL DEFAULT 0,active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE inventory_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL,estimated_weight DECIMAL(8,2) DEFAULT 0,volume DECIMAL(8,2) DEFAULT 0,heavy TINYINT(1) DEFAULT 0,fragile TINYINT(1) DEFAULT 0,additional_charge DECIMAL(10,2) DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE bookings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(30) NOT NULL UNIQUE,user_id INT UNSIGNED NOT NULL,move_type VARCHAR(80) NOT NULL,pickup_address VARCHAR(255) NOT NULL,pickup_city VARCHAR(100),destination_address VARCHAR(255) NOT NULL,destination_city VARCHAR(100),move_date DATE NOT NULL,move_time TIME NOT NULL,vehicle_id INT UNSIGNED NULL,workers TINYINT UNSIGNED DEFAULT 2,notes TEXT,estimated_total DECIMAL(10,2) NOT NULL,status ENUM('Pending','Confirmed','Workers Assigned','Vehicle Assigned','On the Way','Loading','In Transit','Unloading','Completed','Cancelled') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE booking_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL,item_name VARCHAR(120),quantity SMALLINT UNSIGNED DEFAULT 1,weight DECIMAL(8,2) DEFAULT 0,special TINYINT(1) DEFAULT 0,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE booking_services(booking_id INT UNSIGNED NOT NULL,service_id INT UNSIGNED NOT NULL,PRIMARY KEY(booking_id,service_id),FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB;
CREATE TABLE payments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL,amount DECIMAL(10,2) NOT NULL,method ENUM('Cash','Bank Transfer','Easypaisa','JazzCash') DEFAULT 'Cash',status ENUM('Pending','Paid','Partially Paid','Refunded') DEFAULT 'Pending',reference VARCHAR(100),paid_at DATETIME NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE booking_workers(booking_id INT UNSIGNED NOT NULL,worker_id INT UNSIGNED NOT NULL,PRIMARY KEY(booking_id,worker_id),FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(worker_id) REFERENCES workers(id)) ENGINE=InnoDB;
CREATE TABLE invoices(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL UNIQUE,invoice_number VARCHAR(40) NOT NULL UNIQUE,subtotal DECIMAL(10,2) NOT NULL,discount DECIMAL(10,2) DEFAULT 0,total DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE reviews(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,review TEXT NOT NULL,featured TINYINT(1) DEFAULT 0,visible TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE notifications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,message TEXT,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE contact_messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),email VARCHAR(190),phone VARCHAR(40),subject VARCHAR(190),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
-- Demo administrator: email mateenurrehmanmemon@gmail.com, password is documented in README.md (change before deployment).


CREATE TABLE IF NOT EXISTS demo_testimonials (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,demo_key VARCHAR(20) NOT NULL UNIQUE,reviewer_name VARCHAR(120) NOT NULL,city VARCHAR(100) NOT NULL,move_type VARCHAR(100) NOT NULL,rating TINYINT UNSIGNED NOT NULL,review TEXT NOT NULL,visible TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE demo_testimonials SET visible=0;
ON DUPLICATE KEY UPDATE reviewer_name=VALUES(reviewer_name),city=VALUES(city),move_type=VALUES(move_type),rating=VALUES(rating),review=VALUES(review),visible=VALUES(visible);
