INSERT INTO reviews(booking_id,user_id,rating,review,featured) VALUES(4,5,5,'The crew was on time and handled our furniture with care. A really smooth move.',1),(6,2,5,'Quick, professional and kind. Booking was straightforward too.',1),(10,6,5,'Everything arrived safely and the team kept us updated throughout.',1),(4,5,4,'Great service and clear communication from start to finish.',0),(6,2,5,'Would happily recommend EZShift to friends and family.',0),(10,6,5,'Helpful team and an easy moving day.',0),(4,5,4,'The movers were careful and very polite.',0),(6,2,5,'Our office move went smoothly. Thank you!',0);
